import "git.sytue.eu/sytue/one/apps/nucleo/i18n"

// Los textos de Ajustes → Datos (ajustes_datos.go): el cifrado del disco (X-10 del plan)
// y mover la carpeta de datos. Son una de las `tablas` de la cáscara (textos.go), con sus
// traducciones aquí debajo; la prueba de los 26 idiomas los mira igual que a los demás.
var textosDatos = map[string][2]string{ // clave: {es, en}
	"datos.cifrado":               {"Cifrado del disco", "Disk encryption"},
	"datos.cifrado.mirando":       {"Mirando si el disco está cifrado…", "Checking whether the disk is encrypted…"},
	"datos.cifrado.si":            {"El disco de esta carpeta está cifrado (%s): sin tu contraseña, nadie puede leer tus datos aunque se lleve el equipo.", "The disk of this folder is encrypted (%s): without your password, nobody can read your data even if they take the device."},
	"datos.cifrado.no":            {"El disco de esta carpeta no está cifrado: tus datos van en claro y quien acceda al equipo los lee. Activa el cifrado de disco del sistema para protegerlos.", "The disk of this folder is not encrypted: your data is stored in the clear and anyone with access to the device can read it. Turn on your system's disk encryption to protect it."},
	"datos.cifrado.nose":          {"No se puede saber si el disco de esta carpeta está cifrado. Si no lo está, tus datos van en claro y quien acceda al equipo los lee.", "It is not possible to tell whether the disk of this folder is encrypted. If it is not, your data is stored in the clear and anyone with access to the device can read it."},
	"datos.mover.ayuda":           {"Al cambiarla, todo lo que hay se copia a la nueva y se comprueba antes de usarla. La de ahora no se borra sola.", "When you change it, everything here is copied to the new one and checked before it is used. The current one is not deleted automatically."},
	"datos.mover.pregunta":        {"Se copiará todo lo de Sytue Office (%s) a la carpeta nueva y se comprobará la copia; solo entonces las apps la usarán. La carpeta de ahora no se borra. La app se cerrará al terminar.", "Everything in Sytue Office (%s) will be copied to the new folder and the copy checked; only then will the apps use it. The current folder is not deleted. The app will close when it finishes."},
	"datos.mover":                 {"Mover la carpeta de datos", "Move the data folder"},
	"datos.mover.verbo":           {"Mover", "Move"},
	"datos.mover.cerrar":          {"Antes, cierra estas apps de Sytue Office: %s.", "First, close these Sytue Office apps: %s."},
	"datos.mover.cerrarTodas":     {"Antes de seguir, cierra las demás apps de Sytue Office: este sistema no deja ver cuáles están abiertas.", "Before you continue, close the other Sytue Office apps: this system does not show which ones are open."},
	"datos.mover.midiendo":        {"Contando lo que hay…", "Counting what there is…"},
	"datos.mover.copiando":        {"Copiando…", "Copying…"},
	"datos.mover.comprobando":     {"Comprobando la copia…", "Checking the copy…"},
	"datos.mover.hecho":           {"Tus datos ya están en la carpeta nueva y las apps la usarán desde ahora. La de antes sigue donde estaba, con todo: bórrala si ya no la necesitas.", "Your data is now in the new folder and the apps will use it from now on. The old one is still where it was, with everything in it: delete it if you no longer need it."},
	"datos.mover.borrar":          {"Borrar la carpeta de antes", "Delete the old folder"},
	"datos.mover.borrar.pregunta": {"Se borrará de la carpeta de antes todo lo que se ha copiado a la nueva. No se puede deshacer.", "Everything that was copied to the new folder will be deleted from the old one. This cannot be undone."},
	"datos.mover.borrada":         {"Carpeta de antes borrada.", "Old folder deleted."},
	"datos.mover.quedan":          {"No se ha podido borrar todo: algo sigue en la carpeta de antes.", "Not everything could be deleted: something is still in the old folder."},
	"datos.mover.nada":            {"No se ha cambiado nada: tus datos siguen en la carpeta de ahora.", "Nothing has changed: your data is still in the current folder."},
	"datos.mover.noVacia":         {"La carpeta nueva no está vacía. Para no mezclar tus datos con lo que ya hay, elige otra.", "The new folder is not empty. So as not to mix your data with what is already there, choose another one."},
	"datos.mover.misma":           {"Esa ya es tu carpeta de datos.", "That is already your data folder."},
	"datos.mover.dentro":          {"La carpeta nueva no puede estar dentro de la de ahora.", "The new folder cannot be inside the current one."},
	"datos.mover.enUso":           {"Una app de Sytue Office tiene sus datos abiertos. Ciérrala y vuelve a intentarlo.", "A Sytue Office app has its data open. Close it and try again."},
	"datos.mover.sinSitio":        {"No cabe: en el disco de la carpeta nueva quedan %s libres.", "It does not fit: there is %s free on the disk of the new folder."},
	"datos.mover.malo":            {"La copia no ha salido igual que el original, así que no se usa.", "The copy is not identical to the original, so it is not used."},
}

